/* Local portrait atlas; embedded to preserve file:// offline play. */
window.NeonFaceAtlas="data:image/png;base64,";
window.NeonDogPortrait="data:image/png;base64,";
document.querySelectorAll(".character-portrait:not(.portrait-orelha)").forEach(function(portrait){var img=document.createElement("img");img.src=window.NeonFaceAtlas;img.alt="";img.draggable=false;portrait.appendChild(img);});
document.documentElement.style.setProperty("--dog-portrait", "url("+window.NeonDogPortrait+")");
